    "name": "gaius-codius"
  },
  "userConfig": {
    "notesDir": {
      "type": "string",
      "title": "Notes folder",
      "description": "Where notes are stored (default ~/.local/share/ostrakon). OSTRAKON_DIR overrides it.",
      "default": ""
    },
    "pocket": {
      "type": "boolean",
      "title": "Pocket",
      "description": "Show this project's open notes as numbered chips above the prompt (a digit in an empty prompt pulls one in). Off keeps only the ✎.",
      "default": true
